class _UniffiConverterBool:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)

class _UniffiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()




class Brief:
    """
    A one-shot task brief. Maps onto [`octos_ffi::TaskBrief`].
    """

    prompt: "str"
    max_iterations: "typing.Optional[int]"
    def __init__(self, *, prompt: "str", max_iterations: "typing.Optional[int]" = _DEFAULT):
        self.prompt = prompt
        if max_iterations is _DEFAULT:
            self.max_iterations = None
        else:
            self.max_iterations = max_iterations

    def __str__(self):
        return "Brief(prompt={}, max_iterations={})".format(self.prompt, self.max_iterations)

    def __eq__(self, other):
        if self.prompt != other.prompt:
            return False
        if self.max_iterations != other.max_iterations:
            return False
        return True

class _UniffiConverterTypeBrief(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return Brief(
            prompt=_UniffiConverterString.read(buf),
            max_iterations=_UniffiConverterOptionalUInt32.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiConverterString.check_lower(value.prompt)
        _UniffiConverterOptionalUInt32.check_lower(value.max_iterations)

    @staticmethod
    def write(value, buf):
        _UniffiConverterString.write(value.prompt, buf)
        _UniffiConverterOptionalUInt32.write(value.max_iterations, buf)


class Config:
    """
    Runtime configuration. Maps directly onto [`octos_ffi::RuntimeConfig`].

    Supply EITHER `api_key` (a literal key) OR `api_key_env` (the name of a
    process env var holding it). If neither is set, resolution falls back to the
    conventional `{PROVIDER}_API_KEY` env var and then the `octos auth login`
    store — see the credential notes on [`octos_ffi::OctosRuntime::from_config`].
    """

    provider: "str"
    model: "str"
    api_key: "typing.Optional[str]"
    api_key_env: "typing.Optional[str]"
    base_url: "typing.Optional[str]"
    api_type: "typing.Optional[str]"
    """
    API protocol override: `"anthropic"` / `"responses"`. Required to drive a
    `provider:"custom"` Anthropic-compatible endpoint (without it the factory
    defaults to the OpenAI protocol). Usually omitted.
    """

    cwd: "typing.Optional[str]"
    allow_shell: "bool"
    max_iterations: "typing.Optional[int]"
    embedding_model_path: "typing.Optional[str]"
    def __init__(self, *, provider: "str", model: "str", api_key: "typing.Optional[str]" = _DEFAULT, api_key_env: "typing.Optional[str]" = _DEFAULT, base_url: "typing.Optional[str]" = _DEFAULT, api_type: "typing.Optional[str]" = _DEFAULT, cwd: "typing.Optional[str]" = _DEFAULT, allow_shell: "bool" = _DEFAULT, max_iterations: "typing.Optional[int]" = _DEFAULT, embedding_model_path: "typing.Optional[str]" = _DEFAULT):
        self.provider = provider
        self.model = model
        if api_key is _DEFAULT:
            self.api_key = None
        else:
            self.api_key = api_key
        if api_key_env is _DEFAULT:
            self.api_key_env = None
        else:
            self.api_key_env = api_key_env
        if base_url is _DEFAULT:
            self.base_url = None
        else:
            self.base_url = base_url
        if api_type is _DEFAULT:
            self.api_type = None
        else:
            self.api_type = api_type
        if cwd is _DEFAULT:
            self.cwd = None
        else:
            self.cwd = cwd
        if allow_shell is _DEFAULT:
            self.allow_shell = False
        else:
            self.allow_shell = allow_shell
        if max_iterations is _DEFAULT:
            self.max_iterations = None
        else:
            self.max_iterations = max_iterations
        if embedding_model_path is _DEFAULT:
            self.embedding_model_path = None
        else:
            self.embedding_model_path = embedding_model_path

    def __str__(self):
        return "Config(provider={}, model={}, api_key={}, api_key_env={}, base_url={}, api_type={}, cwd={}, allow_shell={}, max_iterations={}, embedding_model_path={})".format(self.provider, self.model, self.api_key, self.api_key_env, self.base_url, self.api_type, self.cwd, self.allow_shell, self.max_iterations, self.embedding_model_path)

    def __eq__(self, other):
        if self.provider != other.provider:
            return False
        if self.model != other.model:
            return False
        if self.api_key != other.api_key:
            return False
        if self.api_key_env != other.api_key_env:
            return False
        if self.base_url != other.base_url:
            return False
        if self.api_type != other.api_type:
            return False
        if self.cwd != other.cwd:
            return False
        if self.allow_shell != other.allow_shell:
            return False
        if self.max_iterations != other.max_iterations:
            return False
        if self.embedding_model_path != other.embedding_model_path:
            return False
        return True

