    iterations: "int"
    tokens: "TokenUsage"
    def __init__(self, *, output: "str", iterations: "int", tokens: "TokenUsage"):
        self.output = output
        self.iterations = iterations
        self.tokens = tokens

    def __str__(self):
        return "TaskResult(output={}, iterations={}, tokens={})".format(self.output, self.iterations, self.tokens)

    def __eq__(self, other):
        if self.output != other.output:
            return False
        if self.iterations != other.iterations:
            return False
        if self.tokens != other.tokens:
            return False
        return True

