class TokenUsage:
    """
    Token accounting for a completed [`Runtime::run_task`].
    """

    input: "int"
    output: "int"
    reasoning: "int"
    cache_read: "int"
    cache_write: "int"
    def __init__(self, *, input: "int", output: "int", reasoning: "int", cache_read: "int", cache_write: "int"):
        self.input = input
        self.output = output
        self.reasoning = reasoning
        self.cache_read = cache_read
        self.cache_write = cache_write

    def __str__(self):
        return "TokenUsage(input={}, output={}, reasoning={}, cache_read={}, cache_write={})".format(self.input, self.output, self.reasoning, self.cache_read, self.cache_write)

    def __eq__(self, other):
        if self.input != other.input:
            return False
        if self.output != other.output:
            return False
        if self.reasoning != other.reasoning:
            return False
        if self.cache_read != other.cache_read:
            return False
        if self.cache_write != other.cache_write:
            return False
        return True

